# Generated by forge. New PyPI dependencies exist on the index (run by .forge/check.sh with
# the project's own Python, 3.11+). Usage: python new_deps.py <forge-tmp> <cooldown-seconds>
# For each changed pyproject.toml, the names its [project] dependencies and
# optional-dependencies, [dependency-groups], [tool.uv] dev-dependencies and
# [tool.poetry.*dependencies] gain over the base copy are looked up on pypi.org: a name that
# does not exist, every release yanked, and a first upload less than <cooldown> ago are
# findings ("path:line message", at the dependency's line). Names served by a private index are
# not looked up: [tool.uv.sources] pinned to an explicit [[tool.uv.index]], and Poetry
# dependencies with a source of priority explicit; path, git and URL sources are not PyPI's.
# The index unreachable: exit 3, "skipped: …". FORGE_REGISTRY_PYPI replaces https://pypi.org
# (a mirror; the tests).
# Exit 0: nothing found; 1: findings printed; 3: cannot run.
import json
import os
import re
import sys
import time
import urllib.error
import urllib.request
from datetime import datetime

try:
    import tomllib
except ImportError:
    print("skipped: tomllib needs Python 3.11+")
    sys.exit(3)

tmp = sys.argv[1]
cooldown = int(sys.argv[2]) if len(sys.argv) > 2 and sys.argv[2].isdigit() else 0
INDEX = os.environ.get("FORGE_REGISTRY_PYPI", "https://pypi.org").rstrip("/")
NAME = re.compile(r"^\s*([A-Za-z0-9][A-Za-z0-9._-]*)")


def norm(n):
    return re.sub(r"[-_.]+", "-", n).lower()


def load(path):
    try:
        with open(path, "rb") as f:
            return tomllib.load(f)
    except (OSError, tomllib.TOMLDecodeError):
        return None


def private(doc):
    """Normalized names a private index (or a non-index source) serves."""
    out = set()
    uv = (doc.get("tool") or {}).get("uv") or {}
    explicit = {i.get("name") for i in uv.get("index") or [] if isinstance(i, dict) and i.get("explicit")}
    for name, src in (uv.get("sources") or {}).items():
        for s in src if isinstance(src, list) else [src]:
            if isinstance(s, dict) and (s.get("index") in explicit or any(k in s for k in ("path", "git", "url", "workspace"))):
                out.add(norm(name))
    poetry = (doc.get("tool") or {}).get("poetry") or {}
    psrc = {s.get("name") for s in poetry.get("source") or [] if isinstance(s, dict) and s.get("priority") == "explicit"}
    for table in poetry_tables(poetry):
        for name, spec in table.items():
            for s in spec if isinstance(spec, list) else [spec]:
                if isinstance(s, dict) and (s.get("source") in psrc or any(k in s for k in ("path", "git", "url"))):
                    out.add(norm(name))
    return out


def poetry_tables(poetry):
    yield poetry.get("dependencies") or {}
    yield poetry.get("dev-dependencies") or {}
    for g in (poetry.get("group") or {}).values():
        if isinstance(g, dict):
            yield g.get("dependencies") or {}


def deps(doc):
    out = set()
    if doc is None:
        return out
    strings = list((doc.get("project") or {}).get("dependencies") or [])
    for v in ((doc.get("project") or {}).get("optional-dependencies") or {}).values():
        strings += v or []
    for v in (doc.get("dependency-groups") or {}).values():
        strings += [x for x in v or [] if isinstance(x, str)]
    strings += ((doc.get("tool") or {}).get("uv") or {}).get("dev-dependencies") or []
    for s in strings:
        if isinstance(s, str) and "@" not in s.split(";")[0]:
            m = NAME.match(s)
            if m:
                out.add(m.group(1))
    for table in poetry_tables(((doc.get("tool") or {}).get("poetry")) or {}):
        out.update(k for k in table if norm(k) != "python")
    return out


def lookup(name):
    url = f"{INDEX}/pypi/{name}/json"
    try:
        with urllib.request.urlopen(urllib.request.Request(url, headers={"Accept": "application/json"}), timeout=20) as r:
            return json.load(r), None
    except urllib.error.HTTPError as e:
        return (None, None) if e.code == 404 else (None, f"{url} answered {e.code}")
    except (urllib.error.URLError, OSError, ValueError) as e:
        return None, str(getattr(e, "reason", e))


found = []
unreachable = ""
with open(os.path.join(tmp, "changed"), encoding="utf-8") as f:
    changed = [l.rstrip("\n") for l in f if l.strip()]
for path in changed:
    if not re.search(r"(^|/)pyproject\.toml$", path) or not os.path.isfile(path):
        continue
    now = load(path)
    if now is None:
        continue
    then = {norm(n) for n in deps(load(os.path.join(tmp, "base", path)))}
    skip = private(now)
    with open(path, encoding="utf-8") as f:
        text = f.read().split("\n")
    for name in sorted(deps(now)):
        if norm(name) in then or norm(name) in skip:
            continue
        pat = re.compile(r"(^|[\"'\s])" + re.escape(name) + r"([\"'\s\[<>=!~;,]|$)", re.I)
        at = next((i + 1 for i, l in enumerate(text) if pat.search(l)), 0)
        doc, err = lookup(name)
        if err:
            unreachable = err
            continue
        if doc is None:
            found.append(f"{path}:{at} {name} does not exist on PyPI; check the name (a hallucinated or typo-squatted package?)")
            continue
        files = [f for files in (doc.get("releases") or {}).values() for f in files]
        if files and all(f.get("yanked") for f in files):
            found.append(f"{path}:{at} {name}: every release on PyPI is yanked")
        uploads = [f.get("upload_time_iso_8601") or f.get("upload_time") for f in files]
        first = min((datetime.fromisoformat(u.replace("Z", "+00:00")).timestamp() for u in uploads if u), default=None)
        if cooldown and first is not None and time.time() - first < cooldown:
            day = datetime.fromtimestamp(first).strftime("%Y-%m-%d")
            found.append(f"{path}:{at} {name} was first uploaded {day}, less than {round(cooldown / 86400)} days ago; a new package needs the user's review before it is used")
for line in found:
    print(line)
if found:
    sys.exit(1)
if unreachable:
    print(f"skipped: registry unreachable ({unreachable})")
    sys.exit(3)
sys.exit(0)
